#!/usr/bin/env node
// Run after changing any image, sound, or cutscene:
//   node scripts/generate-asset-manifest.mjs
// The generated file is intentionally committed so the static site needs no build
// server at runtime.
import { createHash } from 'node:crypto';
import { readdir, readFile, stat, writeFile } from 'node:fs/promises';
import { resolve, relative, sep } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const directories = ['images', 'sounds', 'cutscenes'];
const supported = new Set(['.png', '.jpg', '.jpeg', '.webp', '.svg', '.mp3', '.wav', '.mp4']);

async function filesBelow(directory) {
    const entries = await readdir(directory, { withFileTypes: true });
    const files = [];
    for (const entry of entries) {
        const fullPath = resolve(directory, entry.name);
        if (entry.isDirectory()) files.push(...await filesBelow(fullPath));
        else if (supported.has(entry.name.slice(entry.name.lastIndexOf('.')).toLowerCase())) files.push(fullPath);
    }
    return files;
}

const allFiles = (await Promise.all(directories.map(directory => filesBelow(resolve(root, directory))))).flat().sort();
const assets = {};
for (const file of allFiles) {
    const bytes = await readFile(file);
    const key = relative(root, file).split(sep).join('/');
    assets[key] = {
        bytes: (await stat(file)).size,
        sha256: createHash('sha256').update(bytes).digest('hex')
    };
}
const version = createHash('sha256').update(JSON.stringify(assets)).digest('hex').slice(0, 16);
const output = `// Generated by scripts/generate-asset-manifest.mjs — do not edit manually.\n` +
    `globalThis.ASSET_MANIFEST = Object.freeze({ version: '${version}', assets: Object.freeze(${JSON.stringify(assets, null, 2)}) });\n`;
await writeFile(resolve(root, 'js/asset-manifest.js'), output);
console.log(`Generated ${Object.keys(assets).length} assets (${version}).`);
